\operatorname{MetaSub}_{\lambda x}(\operatorname{xsub}(M,x,N),y,P)=
\begin{cases}
\operatorname{xsub}(M,x,\operatorname{MetaSub}_{\lambda x}(N,y,P)),&x=y,\\
\operatorname{xsub}(\operatorname{MetaSub}_{\lambda x}(M,y,P),x,\operatorname{MetaSub}_{\lambda x}(N,y,P)),&x\ne y\text{ 且 }x\notin \operatorname{FV}_{\lambda x}(P),\\
\operatorname{xsub}(\operatorname{MetaSub}_{\lambda x}(\operatorname{MetaSub}_{\lambda x}(M,x,\operatorname{var}(z)),y,P),z,\operatorname{MetaSub}_{\lambda x}(N,y,P)),&x\ne y\text{ 且 }x\in \operatorname{FV}_{\lambda x}(P),
\end{cases}

\mathsf{PropVarMiss}_{\lambda x}
=\{(\operatorname{xsub}(\operatorname{var}(y),x,N),\operatorname{var}(y)):
x,y\in\mathsf{Var}_{\lambda x},\ x\ne y,\ N\in\mathsf{Tm}_{\lambda x}\},

\mathsf{PropLamFresh}_{\lambda x}
=\{(\operatorname{xsub}(\operatorname{lam}(y,M),x,N),\operatorname{lam}(y,\operatorname{xsub}(M,x,N))):
x,y\in\mathsf{Var}_{\lambda x},\ y\ne x,\ y\notin\operatorname{FV}_{\lambda x}(N),\ M,N\in\mathsf{Tm}_{\lambda x}\},

\mathsf{PropNested}_{\lambda x}
=\{(\operatorname{xsub}(\operatorname{xsub}(M,x,N),y,P),\operatorname{xsub}(\operatorname{xsub}(M,y,P),x,\operatorname{xsub}(N,y,P))):
x,y\in\mathsf{Var}_{\lambda x},\ x\ne y,\ x\notin\operatorname{FV}_{\lambda x}(P),\ M,N,P\in\mathsf{Tm}_{\lambda x}\}.

\mathsf{Delta}_{\lambda x}
=
(\operatorname{xsub},\operatorname{MetaSub}_{\lambda x},\mathsf{PropLamStop}_{\lambda x},\mathsf{PropVarHit}_{\lambda x},\mathsf{PropVarMiss}_{\lambda x},\mathsf{PropApp}_{\lambda x},\mathsf{PropLamFresh}_{\lambda x},\mathsf{PropLamRename}_{\lambda x},\mathsf{PropNested}_{\lambda x},\mathsf{StepCert}_{\lambda x},\operatorname{ctxCert}_{\lambda x},\operatorname{rootSrc}_{\lambda x},\operatorname{rootTgt}_{\lambda x},\mathsf{RedDer}_{\lambda x},\mathsf{ConvStep}_{\lambda x},\mathsf{ConvSeq}_{\lambda x},=_{\lambda x},\to^0_{\lambda x},\mathsf{RSeq}_{\lambda x}),

\to^0_{\lambda x}
=
\mathsf{Beta}_{\lambda x}
\cup\mathsf{PropLamStop}_{\lambda x}
\cup\mathsf{PropVarHit}_{\lambda x}
\cup\mathsf{PropVarMiss}_{\lambda x}
\cup\mathsf{PropApp}_{\lambda x}
\cup\mathsf{PropLamFresh}_{\lambda x}
\cup\mathsf{PropLamRename}_{\lambda x}
\cup\mathsf{PropNested}_{\lambda x},
